class AsyncContainerProcesses:
    """A container's processes."""

    def __init__(self, client: "AsyncContainers", id: str) -> None:
        self._c = client
        self._id = id

    async def output(self, process: str, *, cursor: Optional[int] = None, wait_seconds: Optional[float] = None, max_bytes: Optional[int] = None, follow: Optional[bool] = None) -> ProcessOutput:
        """Returns a process's output after a cursor, and the cursor to read on from. The latest 1 MiB is kept; truncated says when the cursor fell behind."""
        return await self._c.process_output(self._id, process, cursor=cursor, wait_seconds=wait_seconds, max_bytes=max_bytes, follow=follow)

    async def write(self, process: str, *, data: Optional[str] = None, offset: Optional[int] = None, eof: Optional[bool] = None, idempotency_key: Optional[str] = None) -> ProcessWritten:
        """Sends input to a process started with stdinOpen or a pty, and returns how much of its input it has taken."""
        return await self._c.write_process(self._id, process, data=data, offset=offset, eof=eof, idempotency_key=idempotency_key)

    async def signal(self, process: str, *, signal: Optional[Literal["SIGINT", "SIGTERM", "SIGHUP", "SIGQUIT", "SIGUSR1", "SIGUSR2", "SIGKILL", "unknown"]] = None, idempotency_key: Optional[str] = None) -> Process:
        """Sends a signal to a process and its group; a process that ended is not signalled, so a retry is safe."""
        return await self._c.signal_process(self._id, process, signal=signal, idempotency_key=idempotency_key)

    async def list(self) -> ProcessList:
        """Lists a container's processes, newest first: those running and those that ended lately."""
        return await self._c.list_processes(self._id)


class AsyncContainerNetwork:
    """A container's network."""

    def __init__(self, client: "AsyncContainers", id: str) -> None:
        self._c = client
        self._id = id

    async def get(self) -> SandboxNetwork:
        """Returns where a container may connect out."""
        return await self._c.get_network(self._id)

    async def set(self, *, allow_outbound: Optional[List[str]] = None, deny_outbound: Optional[List[str]] = None, idempotency_key: Optional[str] = None) -> SandboxNetwork:
        """Replaces where a container may connect out, for its next connection and within a second for its open ones: those the new rules refuse are cut."""
        return await self._c.set_network(self._id, allow_outbound=allow_outbound, deny_outbound=deny_outbound, idempotency_key=idempotency_key)


class AsyncContainer:
    """One of containers: A machine that runs one OCI image from any registry under Docker on its own network (`start` `runtime-container <image>`), the port it listens on reached at its preview, as Cloud Run and Fly Machines run one."""

    def __init__(self, client: "AsyncContainers", info: SandboxInfo) -> None:
        self._c = client
        #: What it was when last read.
        self.info = info
        self.files = AsyncContainerFiles(client, info.id)
        self.processes = AsyncContainerProcesses(client, info.id)
        self.network = AsyncContainerNetwork(client, info.id)

    @property
    def id(self) -> str:
        """Its id."""
        return self.info.id

    def __repr__(self) -> str:
        return f"AsyncContainer({self.info!r})"

    async def refresh(self, *, wait: Optional[float] = None, if_state: Optional[str] = None) -> "AsyncContainer":
        """Returns a container."""
        self.info = (await self._c.get(self.id, wait=wait, if_state=if_state)).info
        return self

    async def delete(self, *, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Deletes a container, its memory and its disk."""
        return await self._c.delete(self.id, idempotency_key=idempotency_key)

    async def pause(self, *, idempotency_key: Optional[str] = None) -> "AsyncContainer":
        """Pauses a container with its memory and disk kept. A call to it resumes it."""
        self.info = await self._c.pause(self.id, idempotency_key=idempotency_key)
        return self

    async def resume(self, *, idempotency_key: Optional[str] = None) -> "AsyncContainer":
        """Resumes a paused container where it was, its memory and processes as they were."""
        self.info = await self._c.resume(self.id, idempotency_key=idempotency_key)
        return self

    async def exec(self, cmd: Union[str, List[str]], *, cwd: Optional[str] = None, env: Optional[Dict[str, str]] = None, stdin: Optional[str] = None, timeout_seconds: Optional[float] = None, stream: Optional[bool] = None, wait: Optional[bool] = None, stdin_open: Optional[bool] = None, output_encoding: Optional[Literal["utf8", "base64", "unknown"]] = None, pty: Optional["Terminal"] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, idempotency_key: Optional[str] = None) -> Process:
        """Runs a command as a process and returns it once it ended, with its output; with wait false, at once, while it runs. A paused container is resumed first. Asked again with the same Idempotency-Key, it runs nothing more: it returns the first run's process, waiting for its end while it runs."""
        return await self._c.exec(self.id, cwd=cwd, env=env, stdin=stdin, timeout_seconds=timeout_seconds, stream=stream, wait=wait, stdin_open=stdin_open, output_encoding=output_encoding, pty=pty, user=user, cmd=cmd, idempotency_key=idempotency_key)

    async def metrics(self, *, range: Optional[Literal["15m", "1h", "6h", "24h", "7d", "30d", "unknown"]] = None) -> SandboxMetrics:
        """Returns a container's CPU, memory, disks and pressure, as its host reads them from the container's own cgroup over a fifth of a second: never a call into the container, so it does not wake a paused one nor keep one from its idle pause. One that is not running has no reading."""
        return await self._c.metrics(self.id, range=range)

    async def fork(self, *, count: Optional[int] = None, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, secrets: Optional[List[str]] = None, max_cost: Optional[str] = None, idle_pause_seconds: Optional[int] = None, idempotency_key: Optional[str] = None) -> Forked:
        """Copies a container as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies."""
        return await self._c.fork(self.id, count=count, name=name, labels=labels, secrets=secrets, max_cost=max_cost, idle_pause_seconds=idle_pause_seconds, idempotency_key=idempotency_key)

    async def snapshot(self, *, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, image: Optional[str] = None, start: Optional["MachineStart"] = None, idempotency_key: Optional[str] = None) -> Stored:
        """Keeps a container's memory and disk as they are now, a snapshot to start containers from; with `image`, its disk alone as that image's next version. The container runs on. Asked again with the same Idempotency-Key, it returns the same snapshot."""
        return await self._c.snapshot(self.id, name=name, labels=labels, image=image, start=start, idempotency_key=idempotency_key)

    async def update(self, *, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, idle_pause_seconds: Optional[int] = None, vcpu: Optional[int] = None, memory_gb: Optional[float] = None, disk_gb: Optional[float] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, env: Optional[Dict[str, str]] = None, remove_env: Optional[List[str]] = None, max_cost: Optional[str] = None, idempotency_key: Optional[str] = None) -> "AsyncContainer":
        """Changes its name, labels, idle pause, maxCost, environment or sizes; each field left out stays as it is. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on; a smaller size, or a sandbox that is not running, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412."""
        self.info = await self._c.update(self.id, name=name, labels=labels, idle_pause_seconds=idle_pause_seconds, vcpu=vcpu, memory_gb=memory_gb, disk_gb=disk_gb, user=user, env=env, remove_env=remove_env, max_cost=max_cost, idempotency_key=idempotency_key)
        return self

    async def screenshot(self, *, format: Optional[Literal["png", "jpeg", "unknown"]] = None, quality: Optional[int] = None) -> bytes:
        """Returns what a container's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused container is resumed first."""
        return await self._c.screenshot(self.id, format=format, quality=quality)

    async def act(self, actions: List["Action"], *, idempotency_key: Optional[str] = None) -> Acted:
        """Moves, clicks, drags and scrolls the mouse and types on the keyboard of a container's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused container is resumed first."""
        return await self._c.act(self.id, actions=actions, idempotency_key=idempotency_key)

    async def run_code(self, code: str, *, language: Optional[Literal["python", "unknown"]] = None, context: Optional[str] = None, timeout_seconds: Optional[int] = None, idempotency_key: Optional[str] = None) -> CodeRun:
        """Runs a cell of Python in a container as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused container is resumed first."""
        return await self._c.run_code(self.id, language=language, context=context, timeout_seconds=timeout_seconds, code=code, idempotency_key=idempotency_key)


class AsyncContainers:
    """A machine that runs one OCI image from any registry under Docker on its own network (`start` `runtime-container <image>`), the port it listens on reached at its preview, as Cloud Run and Fly Machines run one."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport

    async def create(self, *, vcpu: Optional[int] = None, memory_gb: Optional[float] = None, disk_gb: Optional[float] = None, image: Optional[str] = None, secrets: Optional[List[str]] = None, start: Optional["MachineStart"] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, volumes: Optional[List["VolumeMount"]] = None, run: Optional["SandboxRun"] = None, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, get_or_create: Optional[bool] = None, max_cost: Optional[str] = None, idle_pause_seconds: Optional[int] = None, snapshot: Optional[str] = None, network: Optional["NetworkRules"] = None, env: Optional[Dict[str, str]] = None, idempotency_key: Optional[str] = None) -> AsyncContainer:
        """Creates a container. Asked again with the same Idempotency-Key, it returns the same container."""
        return AsyncContainer(self, SandboxInfo.from_dict(await self._transport.request("POST", f"/v2/containers", body=compact({"vcpu": vcpu, "memoryGB": memory_gb, "diskGB": disk_gb, "image": image, "secrets": secrets, "start": start, "user": user, "volumes": volumes, "run": run, "name": name, "labels": labels, "getOrCreate": get_or_create, "maxCost": max_cost, "idlePauseSeconds": idle_pause_seconds, "snapshot": snapshot, "network": network, "env": env}), idempotency_key=idempotency_key, idempotent=True)))

    async def get(self, id: str, *, wait: Optional[float] = None, if_state: Optional[str] = None) -> AsyncContainer:
        """Returns a container."""
        return AsyncContainer(self, SandboxInfo.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}", query={"wait": wait, "ifState": if_state}, idempotent=True)))

    async def list(self, *, state: Optional[str] = None, name: Optional[str] = None, label: Optional[List[str]] = None, cursor: Optional[str] = None, limit: Optional[int] = None) -> AsyncPage[SandboxInfo]:
        """Lists the project's containers, newest first."""
        return async_page(await self._transport.request("GET", f"/v2/containers", query={"state": state, "name": name, "label": label, "cursor": cursor, "limit": limit}, idempotent=True), SandboxInfo.from_dict, lambda c: self.list(state=state, name=name, label=label, cursor=c, limit=limit))

    async def delete(self, id: str, *, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Deletes a container, its memory and its disk."""
        return SandboxInfo.from_dict(await self._transport.request("DELETE", f"/v2/containers/{quote(id, safe='')}", idempotency_key=idempotency_key))

    async def pause(self, id: str, *, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Pauses a container with its memory and disk kept. A call to it resumes it."""
        return SandboxInfo.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:pause", idempotency_key=idempotency_key))

    async def resume(self, id: str, *, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Resumes a paused container where it was, its memory and processes as they were."""
        return SandboxInfo.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:resume", idempotency_key=idempotency_key))

    async def exec(self, id: str, *, cmd: Union[str, List[str]], cwd: Optional[str] = None, env: Optional[Dict[str, str]] = None, stdin: Optional[str] = None, timeout_seconds: Optional[float] = None, stream: Optional[bool] = None, wait: Optional[bool] = None, stdin_open: Optional[bool] = None, output_encoding: Optional[Literal["utf8", "base64", "unknown"]] = None, pty: Optional["Terminal"] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, idempotency_key: Optional[str] = None) -> Process:
        """Runs a command as a process and returns it once it ended, with its output; with wait false, at once, while it runs. A paused container is resumed first. Asked again with the same Idempotency-Key, it runs nothing more: it returns the first run's process, waiting for its end while it runs."""
        return Process.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:exec", body=compact({"cmd": cmd, "cwd": cwd, "env": env, "stdin": stdin, "timeoutSeconds": timeout_seconds, "stream": stream, "wait": wait, "stdinOpen": stdin_open, "outputEncoding": output_encoding, "pty": pty, "user": user}), idempotency_key=idempotency_key, idempotent=True, runs=True, runs_seconds=timeout_seconds))

    async def read(self, id: str, *, path: str) -> bytes:
        """Returns a file's bytes."""
        return await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/files", query={"path": path}, raw=True, idempotent=True)

    async def write(self, id: str, data: Union[bytes, str], *, path: str, mode: Optional[str] = None, offset: Optional[int] = None, sha256: Optional[str] = None, idempotency_key: Optional[str] = None) -> FileWritten:
        """Writes the request's bytes to a file as they come, of any size (Content-Length required), its folders made: the file whole when they all came, or as it was. With offset, they are written into it in place."""
        return FileWritten.from_dict(await self._transport.request("PUT", f"/v2/containers/{quote(id, safe='')}/files", query={"path": path, "mode": mode, "offset": offset, "sha256": sha256}, data=to_bytes(data), idempotency_key=idempotency_key))

    async def process_output(self, id: str, process: str, *, cursor: Optional[int] = None, wait_seconds: Optional[float] = None, max_bytes: Optional[int] = None, follow: Optional[bool] = None) -> ProcessOutput:
        """Returns a process's output after a cursor, and the cursor to read on from. The latest 1 MiB is kept; truncated says when the cursor fell behind."""
        return ProcessOutput.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/processes/{quote(process, safe='')}/output", query={"cursor": cursor, "waitSeconds": wait_seconds, "maxBytes": max_bytes, "follow": follow}, idempotent=True))

    async def write_process(self, id: str, process: str, *, data: Optional[str] = None, offset: Optional[int] = None, eof: Optional[bool] = None, idempotency_key: Optional[str] = None) -> ProcessWritten:
        """Sends input to a process started with stdinOpen or a pty, and returns how much of its input it has taken."""
        return ProcessWritten.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/processes/{quote(process, safe='')}:write", body=compact({"data": data, "offset": offset, "eof": eof}), idempotency_key=idempotency_key))

    async def signal_process(self, id: str, process: str, *, signal: Optional[Literal["SIGINT", "SIGTERM", "SIGHUP", "SIGQUIT", "SIGUSR1", "SIGUSR2", "SIGKILL", "unknown"]] = None, idempotency_key: Optional[str] = None) -> Process:
        """Sends a signal to a process and its group; a process that ended is not signalled, so a retry is safe."""
        return Process.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/processes/{quote(process, safe='')}:signal", body=compact({"signal": signal}), idempotency_key=idempotency_key, idempotent=True))

    async def list_processes(self, id: str) -> ProcessList:
        """Lists a container's processes, newest first: those running and those that ended lately."""
        return ProcessList.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/processes", idempotent=True))

    async def remove(self, id: str, *, path: str, recursive: Optional[bool] = None, idempotency_key: Optional[str] = None) -> FileRemoved:
        """Removes a file, a link or a directory (recursive for one with contents). One missing is success, removed false."""
        return FileRemoved.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files:remove", body=compact({"path": path, "recursive": recursive}), idempotency_key=idempotency_key))

    async def stat(self, id: str, *, path: str, sha256: Optional[bool] = None) -> FileInfo:
        """Returns what is at a path: a file, a directory or a link, or nothing (exists false). With sha256=true, a file's SHA-256 too."""
        return FileInfo.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/files/stat", query={"path": path, "sha256": sha256}, idempotent=True))

    async def list_files(self, id: str, *, path: Optional[str] = None, depth: Optional[int] = None, limit: Optional[int] = None, hidden: Optional[bool] = None, glob: Optional[str] = None) -> FileList:
        """Lists a directory's entries in path order, to a depth."""
        return FileList.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/files/list", query={"path": path, "depth": depth, "limit": limit, "hidden": hidden, "glob": glob}, idempotent=True))

    async def download_folder(self, id: str, *, path: str, gzip: Optional[bool] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, exclude: Optional[str] = None) -> bytes:
        """Returns a folder as a tar archive (`application/x-tar`, or `application/gzip` with gzip), packed by tar in the container as it streams, of any size; its entries are relative to the folder (`./a.txt`). A folder that fails part way (a file it may not read, or one that changes as it is read) ends as an archive every tar reader refuses, never as a short one that reads whole. At most 4 at once in a container. A paused container is woken first."""
        return await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/files/archive", query={"path": path, "gzip": gzip, "user": user, "exclude": exclude}, raw=True, idempotent=True)

    async def upload_folder(self, id: str, data: Union[bytes, str], *, path: str, user: Optional[Literal["runtime", "root", "unknown"]] = None, idempotency_key: Optional[str] = None) -> FolderUnpacked:
        """Unpacks the request's tar archive (gzip-compressed or not, told by its first bytes) into a folder, made with its parents, by tar in the container as the bytes arrive, of any size, nothing of it kept on disk but what tar writes; returns once tar has ended, or 400 `invalid_archive` with what tar said. A paused container is woken first."""
        return FolderUnpacked.from_dict(await self._transport.request("PUT", f"/v2/containers/{quote(id, safe='')}/files/archive", query={"path": path, "user": user}, data=to_bytes(data), idempotency_key=idempotency_key, idempotent=True))

    async def begin_folder_upload(self, id: str, *, path: str, gzip: Optional[bool] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, idempotency_key: Optional[str] = None) -> FolderUpload:
        """Begins a folder's upload in parts: tar starts in the container, unpacking into the folder each part as it arrives. Send the parts in order by offset (writeFolderUpload), then commitFolderUpload; an upload no call names for 10 minutes is ended. A paused container is woken first."""
        return FolderUpload.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files/archive/uploads", body=compact({"path": path, "gzip": gzip, "user": user}), idempotency_key=idempotency_key))

    async def write_folder_upload(self, id: str, upload: str, data: Union[bytes, str], *, offset: Optional[int] = None, idempotency_key: Optional[str] = None) -> FolderUploadReceived:
        """Sends the request's bytes, a part of the archive at its offset, into tar's input as they arrive, of any size, and returns the bytes received in all once tar took them. A part past them is refused 409 `upload_incomplete`, naming them: send the parts in order."""
        return FolderUploadReceived.from_dict(await self._transport.request("PUT", f"/v2/containers/{quote(id, safe='')}/files/archive/uploads/{quote(upload, safe='')}", query={"offset": offset}, data=to_bytes(data), idempotency_key=idempotency_key, idempotent=True))

    async def commit_folder_upload(self, id: str, upload: str, *, idempotency_key: Optional[str] = None) -> FolderUnpacked:
        """Ends a folder upload's input and returns once tar has ended, as an exec returns once its command has: the folder, or 400 `invalid_archive` with what tar said. A front that restarts meanwhile returns 503 `run_goes_on`; sent again, it returns how tar ended. An upload no call has named for 10 minutes since its last part or commit is ended."""
        return FolderUnpacked.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files/archive/uploads/{quote(upload, safe='')}:commit", idempotency_key=idempotency_key, idempotent=True))

    async def abort_folder_upload(self, id: str, upload: str, *, idempotency_key: Optional[str] = None) -> FolderUploadAborted:
        """Stops a folder upload's tar; what it unpacked so far stays."""
        return FolderUploadAborted.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files/archive/uploads/{quote(upload, safe='')}:abort", idempotency_key=idempotency_key, idempotent=True))

    async def mkdir(self, id: str, *, path: str, parents: Optional[bool] = None, idempotency_key: Optional[str] = None) -> FileMade:
        """Makes a directory, and its parents unless parents is false. One there already is success, created false."""
        return FileMade.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files:mkdir", body=compact({"path": path, "parents": parents}), idempotency_key=idempotency_key, idempotent=True))

    async def rename(self, id: str, *, from_: str, to: str, overwrite: Optional[bool] = None, sha256: Optional[str] = None, size: Optional[int] = None, idempotency_key: Optional[str] = None) -> FileRenamed:
        """Moves a file, a link or a directory; refused 409 when something is at its new path, unless overwrite. With sha256 or size, a file written in parts is put in place once whole: its writes ended, then only a file of that size with every byte written and whose bytes hash to it moves; refused 409 `upload_incomplete` or `checksum_mismatch`, nothing moved. With sha256, it is safe to send again: once moved, it returns the same answer while `from` is gone and `to` holds those bytes."""
        return FileRenamed.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files:rename", body=compact({"from": from_, "to": to, "overwrite": overwrite, "sha256": sha256, "size": size}), idempotency_key=idempotency_key))

    async def link(self, id: str, *, path: str, method: Optional[Literal["GET", "PUT", "unknown"]] = None, expires_in_seconds: Optional[int] = None, filename: Optional[str] = None, max_bytes: Optional[int] = None, wake: Optional[bool] = None, archive: Optional[bool] = None, idempotency_key: Optional[str] = None) -> FileLink:
        """Makes an expiring address for one file that anyone may open with no API key, from a browser, curl or another service: GET downloads it (Range works, so videos play and downloads resume; archive: true downloads a folder as .tar.gz), PUT with the raw body uploads it (up to maxBytes, written whole; Content-Length required). The link acts as the key that made it: an upload link needs write, and the link ends with its key, with revokeLinks or with its container. A paused container is woken for it unless wake is false."""
        return FileLink.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files:link", body=compact({"path": path, "method": method, "expiresInSeconds": expires_in_seconds, "filename": filename, "maxBytes": max_bytes, "wake": wake, "archive": archive}), idempotency_key=idempotency_key))

    async def revoke_links(self, id: str, *, idempotency_key: Optional[str] = None) -> FileLinksRevoked:
        """Ends every file link made for a container so far; links made after work."""
        return FileLinksRevoked.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}/files:revokeLinks", idempotency_key=idempotency_key))

    async def get_network(self, id: str) -> SandboxNetwork:
        """Returns where a container may connect out."""
        return SandboxNetwork.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/network", idempotent=True))

    async def metrics(self, id: str, *, range: Optional[Literal["15m", "1h", "6h", "24h", "7d", "30d", "unknown"]] = None) -> SandboxMetrics:
        """Returns a container's CPU, memory, disks and pressure, as its host reads them from the container's own cgroup over a fifth of a second: never a call into the container, so it does not wake a paused one nor keep one from its idle pause. One that is not running has no reading."""
        return SandboxMetrics.from_dict(await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/metrics", query={"range": range}, idempotent=True))

    async def set_network(self, id: str, *, allow_outbound: Optional[List[str]] = None, deny_outbound: Optional[List[str]] = None, idempotency_key: Optional[str] = None) -> SandboxNetwork:
        """Replaces where a container may connect out, for its next connection and within a second for its open ones: those the new rules refuse are cut."""
        return SandboxNetwork.from_dict(await self._transport.request("PUT", f"/v2/containers/{quote(id, safe='')}/network", body=compact({"allowOutbound": allow_outbound, "denyOutbound": deny_outbound}), idempotency_key=idempotency_key))

    async def fork(self, id: str, *, count: Optional[int] = None, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, secrets: Optional[List[str]] = None, max_cost: Optional[str] = None, idle_pause_seconds: Optional[int] = None, idempotency_key: Optional[str] = None) -> Forked:
        """Copies a container as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies."""
        return Forked.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:fork", body=compact({"count": count, "name": name, "labels": labels, "secrets": secrets, "maxCost": max_cost, "idlePauseSeconds": idle_pause_seconds}), idempotency_key=idempotency_key, idempotent=True))

    async def snapshot(self, id: str, *, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, image: Optional[str] = None, start: Optional["MachineStart"] = None, idempotency_key: Optional[str] = None) -> Stored:
        """Keeps a container's memory and disk as they are now, a snapshot to start containers from; with `image`, its disk alone as that image's next version. The container runs on. Asked again with the same Idempotency-Key, it returns the same snapshot."""
        return Stored.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:snapshot", body=compact({"name": name, "labels": labels, "image": image, "start": start}), idempotency_key=idempotency_key, idempotent=True))

    async def update(self, id: str, *, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, idle_pause_seconds: Optional[int] = None, vcpu: Optional[int] = None, memory_gb: Optional[float] = None, disk_gb: Optional[float] = None, user: Optional[Literal["runtime", "root", "unknown"]] = None, env: Optional[Dict[str, str]] = None, remove_env: Optional[List[str]] = None, max_cost: Optional[str] = None, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Changes its name, labels, idle pause, maxCost, environment or sizes; each field left out stays as it is. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on; a smaller size, or a sandbox that is not running, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412."""
        return SandboxInfo.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:update", body=compact({"name": name, "labels": labels, "idlePauseSeconds": idle_pause_seconds, "vcpu": vcpu, "memoryGB": memory_gb, "diskGB": disk_gb, "user": user, "env": env, "removeEnv": remove_env, "maxCost": max_cost}), idempotency_key=idempotency_key))

    async def screenshot(self, id: str, *, format: Optional[Literal["png", "jpeg", "unknown"]] = None, quality: Optional[int] = None) -> bytes:
        """Returns what a container's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused container is resumed first."""
        return await self._transport.request("GET", f"/v2/containers/{quote(id, safe='')}/screenshot", query={"format": format, "quality": quality}, raw=True, idempotent=True)

    async def act(self, id: str, *, actions: List["Action"], idempotency_key: Optional[str] = None) -> Acted:
        """Moves, clicks, drags and scrolls the mouse and types on the keyboard of a container's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused container is resumed first."""
        return Acted.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:act", body=compact({"actions": actions}), idempotency_key=idempotency_key))

    async def run_code(self, id: str, *, code: str, language: Optional[Literal["python", "unknown"]] = None, context: Optional[str] = None, timeout_seconds: Optional[int] = None, idempotency_key: Optional[str] = None) -> CodeRun:
        """Runs a cell of Python in a container as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused container is resumed first."""
        return CodeRun.from_dict(await self._transport.request("POST", f"/v2/containers/{quote(id, safe='')}:runCode", body=compact({"code": code, "language": language, "context": context, "timeoutSeconds": timeout_seconds}), idempotency_key=idempotency_key))


